        public static string? ResolveTvgId(string? currentTvgId, string? tvgName, string? groupTitle, string? name)
        {
            var mapped = TryResolveMappedTvgId(tvgName, groupTitle, name);
            if (!string.IsNullOrWhiteSpace(mapped))
            {
                return mapped;
            }

            if (!string.IsNullOrWhiteSpace(currentTvgId))
            {
                return currentTvgId.Trim();
            }

            return null;
        }

        public static string? TryResolveMappedTvgId(string? tvgName, string? groupTitle, string? name)
        {
            foreach (var candidate in new[] { tvgName, name, groupTitle })
            {
                if (TryLookup(candidate, out var tvgId))
                {
                    return tvgId;
                }
            }

            return null;
        }

        private static bool TryLookup(string? value, out string tvgId)
        {
            tvgId = string.Empty;
            if (string.IsNullOrWhiteSpace(value))
            {
                return false;
            }

            var key = NormalizeKey(value);
            if (key.Length == 0)
            {
                return false;
            }

            if (_xmltvIds.TryGetValue(key, out var mappedTvgId) && !string.IsNullOrWhiteSpace(mappedTvgId))
            {
                tvgId = mappedTvgId;
                return true;
            }

            return false;
        }

        private static string NormalizeKey(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
            {
                return string.Empty;
            }

            var text = value.Trim();
            text = Regex.Replace(text, @"^\s*\d+\s*(?:[-:?.]\s*)?", string.Empty, RegexOptions.CultureInvariant);
            text = text.Normalize(NormalizationForm.FormD);
            var sb = new StringBuilder(text.Length);
            foreach (var ch in text)
            {
                var category = CharUnicodeInfo.GetUnicodeCategory(ch);
                if (category == UnicodeCategory.NonSpacingMark)
                {
                    continue;
                }

                if (char.IsLetterOrDigit(ch))
                {
                    sb.Append(char.ToUpperInvariant(ch));
                }
            }

            return sb.ToString();
        }
    }
